SET NAMES utf8mb4;

DROP DATABASE IF EXISTS ecommerce_db;

CREATE DATABASE ecommerce_db CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;

USE ecommerce_db;

CREATE TABLE categorias (
    id_categoria INT UNSIGNED NOT NULL AUTO_INCREMENT,
    nombre VARCHAR(80) NOT NULL,
    descripcion VARCHAR(255),
    cantidad_productos INT UNSIGNED NOT NULL DEFAULT 0,
    CONSTRAINT pk_categorias PRIMARY KEY (id_categoria),
    CONSTRAINT uq_categorias_nombre UNIQUE (nombre)
) ENGINE = InnoDB;

CREATE TABLE proveedores (
    id_proveedor INT UNSIGNED NOT NULL AUTO_INCREMENT,
    nombre VARCHAR(120) NOT NULL,
    nit VARCHAR(15),
    email_contacto VARCHAR(120),
    telefono_contacto VARCHAR(20),
    ciudad VARCHAR(60),
    activo BOOLEAN NOT NULL DEFAULT TRUE,
    CONSTRAINT pk_proveedores PRIMARY KEY (id_proveedor),
    CONSTRAINT uq_proveedores_nit UNIQUE (nit),
    CONSTRAINT uq_proveedores_email_contacto UNIQUE (email_contacto)
) ENGINE = InnoDB;

CREATE TABLE sucursales (
    id_sucursal INT UNSIGNED NOT NULL AUTO_INCREMENT,
    nombre VARCHAR(80) NOT NULL,
    ciudad VARCHAR(60) NOT NULL,
    direccion VARCHAR(150) NOT NULL,
    telefono VARCHAR(20),
    activa BOOLEAN NOT NULL DEFAULT TRUE,
    CONSTRAINT pk_sucursales PRIMARY KEY (id_sucursal),
    CONSTRAINT uq_sucursales_nombre UNIQUE (nombre)
) ENGINE = InnoDB;

CREATE TABLE usuarios_sucursal (
    id_usuario_sucursal INT UNSIGNED NOT NULL AUTO_INCREMENT,
    usuario_mysql VARCHAR(32) NOT NULL,
    id_sucursal INT UNSIGNED NOT NULL,
    fecha_asignacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_usuarios_sucursal PRIMARY KEY (id_usuario_sucursal),
    CONSTRAINT uq_usuarios_sucursal_usuario_mysql UNIQUE (usuario_mysql),
    CONSTRAINT fk_usuarios_sucursal_sucursal FOREIGN KEY (id_sucursal) REFERENCES sucursales (id_sucursal) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE = InnoDB;

CREATE TABLE productos (
    id_producto INT UNSIGNED NOT NULL AUTO_INCREMENT,
    id_categoria INT UNSIGNED NOT NULL,
    id_proveedor INT UNSIGNED NOT NULL,
    nombre VARCHAR(150) NOT NULL,
    descripcion TEXT,
    sku VARCHAR(20) NOT NULL,
    precio DECIMAL(12,2) NOT NULL,
    costo DECIMAL(12,2) NOT NULL,
    stock INT NOT NULL DEFAULT 0,
    stock_minimo INT NOT NULL DEFAULT 5,
    peso_kg DECIMAL(8,3) NOT NULL DEFAULT 0,
    ubicacion VARCHAR(40),
    activo BOOLEAN NOT NULL DEFAULT TRUE,
    fecha_creacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    fecha_modificacion DATETIME,
    eliminado_en DATETIME,
    CONSTRAINT pk_productos PRIMARY KEY (id_producto),
    CONSTRAINT uq_productos_nombre UNIQUE (nombre),
    CONSTRAINT uq_productos_sku UNIQUE (sku),
    CONSTRAINT chk_productos_precio CHECK (precio > 0),
    CONSTRAINT chk_productos_costo CHECK (costo >= 0),
    CONSTRAINT chk_productos_stock CHECK (stock >= 0),
    CONSTRAINT chk_productos_stock_minimo CHECK (stock_minimo >= 0),
    CONSTRAINT chk_productos_peso_kg CHECK (peso_kg >= 0),
    INDEX idx_productos_categoria (id_categoria),
    INDEX idx_productos_proveedor (id_proveedor),
    INDEX idx_productos_activo_stock (activo, stock),
    CONSTRAINT fk_productos_categoria FOREIGN KEY (id_categoria) REFERENCES categorias (id_categoria) ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT fk_productos_proveedor FOREIGN KEY (id_proveedor) REFERENCES proveedores (id_proveedor) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE = InnoDB;

CREATE TABLE clientes (
    id_cliente INT UNSIGNED NOT NULL AUTO_INCREMENT,
    nombre VARCHAR(60) NOT NULL,
    apellido VARCHAR(60) NOT NULL,
    email VARCHAR(120) NOT NULL,
    contrasena_hash CHAR(64) NOT NULL,
    salt CHAR(16) NOT NULL,
    telefono VARCHAR(20),
    fecha_nacimiento DATE,
    direccion_envio VARCHAR(200),
    ciudad VARCHAR(60),
    departamento VARCHAR(60),
    id_referido_por INT UNSIGNED,
    total_gastado DECIMAL(12,2) NOT NULL DEFAULT 0,
    fecha_ultimo_pedido DATETIME,
    nivel_lealtad ENUM('Bronce','Plata','Oro') NOT NULL DEFAULT 'Bronce',
    fecha_registro DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    activo BOOLEAN NOT NULL DEFAULT TRUE,
    eliminado_en DATETIME,
    CONSTRAINT pk_clientes PRIMARY KEY (id_cliente),
    CONSTRAINT uq_clientes_email UNIQUE (email),
    CONSTRAINT chk_clientes_email CHECK (REGEXP_LIKE(email, '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$')),
    CONSTRAINT chk_clientes_total_gastado CHECK (total_gastado >= 0),
    INDEX idx_clientes_ciudad (ciudad),
    INDEX idx_clientes_fecha_registro (fecha_registro),
    CONSTRAINT fk_clientes_referido_por FOREIGN KEY (id_referido_por) REFERENCES clientes (id_cliente) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE = InnoDB;

CREATE TABLE ventas (
    id_venta INT UNSIGNED NOT NULL AUTO_INCREMENT,
    id_cliente INT UNSIGNED NOT NULL,
    id_sucursal INT UNSIGNED NOT NULL,
    fecha_venta DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    estado ENUM('Pendiente de Pago','Pagado','Procesando','Enviado','Entregado','Cancelado','Devuelto') NOT NULL DEFAULT 'Pendiente de Pago',
    total DECIMAL(12,2) NOT NULL DEFAULT 0,
    metodo_pago ENUM('Tarjeta de credito','Tarjeta debito','PSE','Nequi','Contraentrega'),
    fecha_pago DATETIME,
    direccion_envio VARCHAR(200),
    CONSTRAINT pk_ventas PRIMARY KEY (id_venta),
    CONSTRAINT chk_ventas_total CHECK (total >= 0),
    INDEX idx_ventas_cliente_fecha (id_cliente, fecha_venta),
    INDEX idx_ventas_sucursal (id_sucursal),
    INDEX idx_ventas_fecha (fecha_venta),
    INDEX idx_ventas_estado (estado),
    CONSTRAINT fk_ventas_cliente FOREIGN KEY (id_cliente) REFERENCES clientes (id_cliente) ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT fk_ventas_sucursal FOREIGN KEY (id_sucursal) REFERENCES sucursales (id_sucursal) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE = InnoDB;

CREATE TABLE detalle_venta (
    id_detalle INT UNSIGNED NOT NULL AUTO_INCREMENT,
    id_venta INT UNSIGNED NOT NULL,
    id_producto INT UNSIGNED NOT NULL,
    cantidad INT NOT NULL,
    precio_unitario_congelado DECIMAL(12,2) NOT NULL,
    subtotal DECIMAL(12,2) GENERATED ALWAYS AS (cantidad * precio_unitario_congelado) STORED,
    cantidad_devuelta INT NOT NULL DEFAULT 0,
    CONSTRAINT pk_detalle_venta PRIMARY KEY (id_detalle),
    CONSTRAINT uq_detalle_venta_producto UNIQUE (id_venta, id_producto),
    CONSTRAINT chk_detalle_venta_cantidad CHECK (cantidad > 0),
    CONSTRAINT chk_detalle_venta_precio_unitario_congelado CHECK (precio_unitario_congelado > 0),
    CONSTRAINT chk_detalle_venta_devuelta CHECK (cantidad_devuelta BETWEEN 0 AND cantidad),
    INDEX idx_detalle_venta_producto (id_producto),
    CONSTRAINT fk_detalle_venta_venta FOREIGN KEY (id_venta) REFERENCES ventas (id_venta) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_detalle_venta_producto FOREIGN KEY (id_producto) REFERENCES productos (id_producto) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE = InnoDB;

CREATE TABLE carritos (
    id_carrito INT UNSIGNED NOT NULL AUTO_INCREMENT,
    id_cliente INT UNSIGNED NOT NULL,
    estado ENUM('Activo','Convertido','Abandonado') NOT NULL DEFAULT 'Activo',
    id_venta INT UNSIGNED,
    fecha_creacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    fecha_actualizacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_carritos PRIMARY KEY (id_carrito),
    INDEX idx_carritos_estado_fecha (estado, fecha_actualizacion),
    CONSTRAINT fk_carritos_cliente FOREIGN KEY (id_cliente) REFERENCES clientes (id_cliente) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_carritos_venta FOREIGN KEY (id_venta) REFERENCES ventas (id_venta) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE = InnoDB;

CREATE TABLE carrito_detalle (
    id_carrito_detalle INT UNSIGNED NOT NULL AUTO_INCREMENT,
    id_carrito INT UNSIGNED NOT NULL,
    id_producto INT UNSIGNED NOT NULL,
    cantidad INT NOT NULL,
    fecha_agregado DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_carrito_detalle PRIMARY KEY (id_carrito_detalle),
    CONSTRAINT uq_carrito_detalle_producto UNIQUE (id_carrito, id_producto),
    CONSTRAINT chk_carrito_detalle_cantidad CHECK (cantidad > 0),
    CONSTRAINT fk_carrito_detalle_carrito FOREIGN KEY (id_carrito) REFERENCES carritos (id_carrito) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_carrito_detalle_producto FOREIGN KEY (id_producto) REFERENCES productos (id_producto) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB;

CREATE TABLE promociones (
    id_promocion INT UNSIGNED NOT NULL AUTO_INCREMENT,
    codigo VARCHAR(30) NOT NULL,
    descripcion VARCHAR(200),
    porcentaje_descuento DECIMAL(5,2) NOT NULL,
    fecha_inicio DATETIME NOT NULL,
    fecha_fin DATETIME NOT NULL,
    activa BOOLEAN NOT NULL DEFAULT TRUE,
    id_producto INT UNSIGNED,
    CONSTRAINT pk_promociones PRIMARY KEY (id_promocion),
    CONSTRAINT uq_promociones_codigo UNIQUE (codigo),
    CONSTRAINT chk_promociones_porcentaje_descuento CHECK (porcentaje_descuento > 0 AND porcentaje_descuento <= 90),
    CONSTRAINT chk_promociones_fechas CHECK (fecha_fin > fecha_inicio),
    INDEX idx_promociones_vigencia (activa, fecha_fin),
    CONSTRAINT fk_promociones_producto FOREIGN KEY (id_producto) REFERENCES productos (id_producto) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE = InnoDB;

CREATE TABLE visitas_producto (
    id_visita INT UNSIGNED NOT NULL AUTO_INCREMENT,
    id_producto INT UNSIGNED NOT NULL,
    id_cliente INT UNSIGNED,
    fecha_visita DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_visitas_producto PRIMARY KEY (id_visita),
    INDEX idx_visitas_producto_fecha (id_producto, fecha_visita),
    CONSTRAINT fk_visitas_producto_producto FOREIGN KEY (id_producto) REFERENCES productos (id_producto) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_visitas_producto_cliente FOREIGN KEY (id_cliente) REFERENCES clientes (id_cliente) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE = InnoDB;

CREATE TABLE resenas_producto (
    id_resena INT UNSIGNED NOT NULL AUTO_INCREMENT,
    id_producto INT UNSIGNED NOT NULL,
    id_cliente INT UNSIGNED NOT NULL,
    calificacion TINYINT UNSIGNED NOT NULL,
    comentario TEXT,
    fecha_resena DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_resenas_producto PRIMARY KEY (id_resena),
    CONSTRAINT uq_resenas_cliente_producto UNIQUE (id_cliente, id_producto),
    CONSTRAINT chk_resenas_producto_calificacion CHECK (calificacion BETWEEN 1 AND 5),
    INDEX idx_resenas_producto (id_producto),
    CONSTRAINT fk_resenas_producto_producto FOREIGN KEY (id_producto) REFERENCES productos (id_producto) ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT fk_resenas_producto_cliente FOREIGN KEY (id_cliente) REFERENCES clientes (id_cliente) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB;

CREATE TABLE creditos_cliente (
    id_credito INT UNSIGNED NOT NULL AUTO_INCREMENT,
    id_cliente INT UNSIGNED NOT NULL,
    id_venta INT UNSIGNED,
    monto DECIMAL(12,2) NOT NULL,
    motivo VARCHAR(200) NOT NULL,
    usado BOOLEAN NOT NULL DEFAULT FALSE,
    fecha_creacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_creditos_cliente PRIMARY KEY (id_credito),
    CONSTRAINT chk_creditos_cliente_monto CHECK (monto > 0),
    CONSTRAINT fk_creditos_cliente_cliente FOREIGN KEY (id_cliente) REFERENCES clientes (id_cliente) ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT fk_creditos_cliente_venta FOREIGN KEY (id_venta) REFERENCES ventas (id_venta) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE = InnoDB;

CREATE TABLE ajustes_stock (
    id_ajuste INT UNSIGNED NOT NULL AUTO_INCREMENT,
    id_producto INT UNSIGNED NOT NULL,
    stock_anterior INT NOT NULL,
    stock_nuevo INT NOT NULL,
    motivo VARCHAR(200) NOT NULL,
    usuario VARCHAR(100) NOT NULL,
    fecha_ajuste DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_ajustes_stock PRIMARY KEY (id_ajuste),
    CONSTRAINT chk_ajustes_stock_stock_nuevo CHECK (stock_nuevo >= 0),
    CONSTRAINT fk_ajustes_stock_producto FOREIGN KEY (id_producto) REFERENCES productos (id_producto) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB;

CREATE TABLE notificaciones (
    id_notificacion INT UNSIGNED NOT NULL AUTO_INCREMENT,
    id_venta INT UNSIGNED NOT NULL,
    canal ENUM('Email','SMS','Webhook') NOT NULL DEFAULT 'Email',
    mensaje VARCHAR(255) NOT NULL,
    enviada BOOLEAN NOT NULL DEFAULT FALSE,
    fecha_creacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_notificaciones PRIMARY KEY (id_notificacion),
    INDEX idx_notificaciones_enviada (enviada),
    CONSTRAINT fk_notificaciones_venta FOREIGN KEY (id_venta) REFERENCES ventas (id_venta) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB;

CREATE TABLE permisos_usuario (
    id_permiso INT UNSIGNED NOT NULL AUTO_INCREMENT,
    usuario_mysql VARCHAR(32) NOT NULL,
    rol VARCHAR(40) NOT NULL,
    activo BOOLEAN NOT NULL DEFAULT TRUE,
    otorgado_por VARCHAR(100) NOT NULL,
    fecha_asignacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    fecha_modificacion DATETIME,
    CONSTRAINT pk_permisos_usuario PRIMARY KEY (id_permiso),
    CONSTRAINT uq_permisos_usuario_rol UNIQUE (usuario_mysql, rol)
) ENGINE = InnoDB;

