UPDATE ventas v
JOIN (
    SELECT id_venta, SUM(subtotal) AS total
    FROM detalle_venta
    GROUP BY id_venta
) dv ON dv.id_venta = v.id_venta
SET v.total = dv.total;

UPDATE productos p
JOIN (
    SELECT dv.id_producto,
           SUM(dv.cantidad) AS vendidos,
           SUM(dv.cantidad_devuelta) AS devueltos
    FROM detalle_venta dv
    JOIN ventas v ON v.id_venta = dv.id_venta
    WHERE v.estado <> 'Cancelado'
    GROUP BY dv.id_producto
) mov ON mov.id_producto = p.id_producto
SET p.stock = p.stock - mov.vendidos + mov.devueltos;

UPDATE clientes c
LEFT JOIN (
    SELECT id_cliente,
           SUM(CASE WHEN estado IN ('Pagado', 'Procesando', 'Enviado', 'Entregado') THEN total ELSE 0 END) AS gastado,
           MAX(fecha_venta) AS ultimo
    FROM ventas
    GROUP BY id_cliente
) v ON v.id_cliente = c.id_cliente
SET c.total_gastado = COALESCE(v.gastado, 0),
    c.fecha_ultimo_pedido = v.ultimo,
    c.nivel_lealtad = CASE
        WHEN COALESCE(v.gastado, 0) >= 5000000 THEN 'Oro'
        WHEN COALESCE(v.gastado, 0) >= 1500000 THEN 'Plata'
        ELSE 'Bronce'
    END;

UPDATE categorias cat
SET cat.cantidad_productos = (
    SELECT COUNT(*)
    FROM productos p
    WHERE p.id_categoria = cat.id_categoria
);
